/* Variable definitions
-----------------------
<Variable name="bodybackground" description="Background" type="background" color="#f6f7fb" default="$(color) url() repeat fixed top left" value="$(color) url() repeat fixed top left"/>
<Variable name="maincolor" description="Primary Color" type="color" default="#28a745"  value="#28a745"/>
<Variable name="maindarkcolor" description="Primary Dark Color" type="color" default="#48494d"  value="#48494d"/>
-----------------------
*/
/*****************************************
reset.css
******************************************/
html, body, .section, .widget, div, span, applet, object, iframe,
h1, h2, h3, h4, h5, h6, p, blockquote, pre,
a, abbr, acronym, address, big, cite, code,
del, dfn, em, font, img, ins, kbd, q, s, samp,
small, strike, strong, sub, sup, tt, var,
dl, dt, dd, ol, ul, li,
fieldset, form, label, legend,
table, caption, tbody, tfoot, thead, tr, th, td, figure {    margin: 0;    padding: 0;}
html {   overflow-x: hidden;}
a {text-decoration:none;color:#000;}
article,aside,details,figcaption,figure,
footer,header,hgroup,menu,nav,section {     display:block;}
table {    border-collapse: separate;    border-spacing: 0;}
caption, th, td {    text-align: left;    font-weight: normal;}
blockquote:before, blockquote:after,
q:before, q:after {    content: "";}
.quickedit, .home-link{display:none;}
blockquote, q {    quotes: "" "";}
sup{    vertical-align: super;    font-size:smaller;}
code{    font-family: 'Quicksand', monospace;    font-size:12px;    color:#272727;}
::selection {background:transparent; text-shadow:#000 0 0 2px;}
::-moz-selection {background:transparent; text-shadow:#000 0 0 2px;}
::-webkit-selection {background:transparent; text-shadow:#000 0 0 2px;}
::-o-selection {background:transparent; text-shadow:#000 0 0 2px;}
a img{	border: none;}
ol, ul { padding:0;  margin:0;  text-align: left;  }
ol li { list-style-type: decimal;  padding:0 0 5px;  }
ul li { list-style-type: disc;  padding: 0 0 5px;  }
ul ul, ol ol { padding: 0; }
#navbar-iframe, .navbar {   height:0px;   visibility:hidden;   display:none   }
#HTML300, #Text100, .post-footer-line.post-footer-line-1, .post-footer-line.post-footer-line-2 , .post-footer-line.post-footer-line-3 {
display: none;
}
.item-control {
display: none !important;
}
h2.date-header, h4.date-header {display:none;margin:1.5em 0 .5em}
h1, h2, h3, h4, h5, h6 {
font-family:'Poppins', sans-serif;
font-weight: 400;
color: #2e2e2e;
}
@media print{
.top-bar, .navi-menu-wrap, #sidebar-wrapper, .share-box, .comments, #lower, .post-footer, #ads-blog-bottom, .bottom-bar-social {
display: none!important;
}
.jugas_footer_copyright {
    display: block!important;
    text-align: center!important;
}
#main-wrapper {
width:100%!important;
max-width:100%!important;
}
}
img {
    max-width: 100%;
    vertical-align: middle;
    height: auto;
}
* {
    outline: 0;
    transition: all .3s ease;
    -webkit-transition: all .3s ease;
    -moz-transition: all .3s ease;
    -o-transition: all .3s ease;
}
*:focus-visible {
    outline: 2px solid #28a745;
    outline-offset: 2px;
}

/* Links - Green Theme */
a {
    color: #28a745;
    text-decoration: none;
    transition: color 0.3s ease;
}

a:hover {
    color: #34ce57;
    text-decoration: underline;
}

/* Buttons - Green Theme */
.btn-primary {
    background-color: #28a745;
    border-color: #28a745;
    color: #ffffff;
}

.btn-primary:hover {
    background-color: #34ce57;
    border-color: #34ce57;
    color: #ffffff;
}

.btn-success {
    background-color: #28a745;
    border-color: #28a745;
}

.btn-success:hover {
    background-color: #34ce57;
    border-color: #34ce57;
}
@media (prefers-reduced-motion: reduce) {
    * {
        transition: none !important;
        animation: none !important;
    }
}
.post-body a:visited {
color:#FF0000;
}
/*****************************************
Custom css starts
******************************************/
body {
color: #2e2e2e;
font-family: 'Nunito', sans-serif;
font-size: 14px;
font-weight: normal;
line-height: 21px;
background: $bodybackground;
}

.post-thumb {transition: opacity .17s ease,transform .17s ease;display: block;position: relative;width: 100%;height: 100%;object-fit: cover;z-index: 1;border-radius: 2px;position: relative}

/* ===== MODERN UI ENHANCEMENTS - Bootstrap 5 Compatible ===== */
/* Glassmorphism Effect */
.glass-effect {
    background: rgba(255, 255, 255, 0.85);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    border: 1px solid rgba(255, 255, 255, 0.3);
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.1);
}

/* Parallax Background */
.parallax-section {
    background-attachment: fixed;
    background-position: center;
    background-repeat: no-repeat;
    background-size: cover;
    position: relative;
}

/* Hero Section Enhanced - Green Theme */
.hero-section {
    min-height: 35vh;
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(135deg, rgba(40, 167, 69, 0.1) 0%, rgba(72, 73, 77, 0.05) 100%);
    position: relative;
    overflow: hidden;
}

.hero-section::before {
    content: '';
    position: absolute;
    top: -50%;
    left: -50%;
    width: 200%;
    height: 200%;
    background: radial-gradient(circle, rgba(40, 167, 69, 0.1) 0%, transparent 70%);
    animation: pulse 15s ease-in-out infinite;
}

@keyframes pulse {
    0%, 100% { transform: scale(1); }
    50% { transform: scale(1.1); }
}

/* Scroll Animations */
.fade-in-up {
    opacity: 0;
    transform: translateY(30px);
    transition: opacity 0.6s ease-out, transform 0.6s ease-out;
}

.fade-in-up.visible {
    opacity: 1;
    transform: translateY(0);
}

.fade-in-left {
    opacity: 0;
    transform: translateX(-30px);
    transition: opacity 0.6s ease-out, transform 0.6s ease-out;
}

.fade-in-left.visible {
    opacity: 1;
    transform: translateX(0);
}

.fade-in-right {
    opacity: 0;
    transform: translateX(30px);
    transition: opacity 0.6s ease-out, transform 0.6s ease-out;
}

.fade-in-right.visible {
    opacity: 1;
    transform: translateX(0);
}

/* Microinteractions */
.btn-hover-effect {
    position: relative;
    overflow: hidden;
    transition: all 0.3s ease;
}

.btn-hover-effect::after {
    content: '';
    position: absolute;
    top: 50%;
    left: 50%;
    width: 0;
    height: 0;
    background: rgba(255, 255, 255, 0.3);
    border-radius: 50%;
    transform: translate(-50%, -50%);
    transition: width 0.6s ease, height 0.6s ease;
}

.btn-hover-effect:hover::after {
    width: 300px;
    height: 300px;
}

/* Card Hover Effects */
.card-hover {
    transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.card-hover:hover {
    transform: translateY(-10px);
    box-shadow: 0 20px 40px rgba(0, 0, 0, 0.15);
}

/* Icon Animations - Green Tones */
.icon-bounce:hover {
    animation: bounce 0.5s ease;
    color: #28a745 !important;
}

@keyframes bounce {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-10px); }
}

/* Icons - Green Color Scheme */
.fa, .fas, .far, .fab, .fal {
    color: #28a745;
}

/* Social Icons - Green Hover */
.social-icons a:hover,
.fa-facebook:hover,
.fa-twitter:hover,
.fa-pinterest:hover,
.fa-linkedin:hover,
.fa-whatsapp:hover {
    color: #28a745 !important;
}

/* Sticky CTA */
.sticky-cta {
    position: fixed;
    bottom: 20px;
    right: 20px;
    z-index: 1000;
    animation: slideIn 0.5s ease-out;
}

@keyframes slideIn {
    from {
        transform: translateX(100%);
        opacity: 0;
    }
    to {
        transform: translateX(0);
        opacity: 1;
    }
}

/* Progress Bar */
.scroll-progress {
    position: fixed;
    top: 0;
    left: 0;
    height: 3px;
    background: linear-gradient(90deg, #28a745, #34ce57);
    z-index: 9999;
    transition: width 0.1s ease;
}

/* Testimonial Cards */
.testimonial-card {
    background: linear-gradient(145deg, #ffffff 0%, #f8f9fa 100%);
    border-radius: 15px;
    padding: 30px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
    transition: all 0.3s ease;
}

.testimonial-card:hover {
    transform: scale(1.02);
    box-shadow: 0 15px 40px rgba(0, 0, 0, 0.15);
}

/* Counter Animation */
.counter {
    font-size: 3rem;
    font-weight: bold;
    color: #28a745;
}

/* Social Proof Section */
.social-proof {
    background: linear-gradient(135deg, #f8f9fa 0%, #e9ecef 100%);
    padding: 60px 0;
}

/* Dark Mode Support - Complete Green Theme */
@media (prefers-color-scheme: dark) {
    body {
        background-color: #1a1a1a;
        color: #e0e0e0;
        font-family: 'Nunito', sans-serif;
    }

    .glass-effect {
        background: rgba(30, 30, 30, 0.85);
        border: 1px solid rgba(40, 167, 69, 0.3);
    }

    .testimonial-card {
        background: linear-gradient(145deg, #2d2d2d 0%, #1a1a1a 100%);
        color: #ffffff;
        border: 1px solid rgba(40, 167, 69, 0.2);
    }

    .hero-section {
        background: linear-gradient(135deg, rgba(40, 167, 69, 0.15) 0%, rgba(26, 26, 26, 0.05) 100%);
    }

    .card-hover:hover {
        box-shadow: 0 20px 40px rgba(40, 167, 69, 0.2);
    }

    .fa, .fas, .far, .fab, .fal {
        color: #28a745;
    }

    a {
        color: #28a745;
    }

    a:hover {
        color: #34ce57;
    }

    h1, h2, h3, h4, h5, h6 {
        color: #ffffff;
        font-family: 'Poppins', sans-serif;
    }

    .social-proof {
        background: linear-gradient(135deg, #2d2d2d 0%, #1a1a1a 100%);
    }

    .counter {
        color: #28a745;
    }

    /* Buttons in Dark Mode */
    .btn-primary {
        background-color: #28a745;
        border-color: #28a745;
        color: #ffffff;
    }

    .btn-primary:hover {
        background-color: #34ce57;
        border-color: #34ce57;
    }

    /* Form Elements */
    input, textarea, select {
        background-color: #2d2d2d;
        border-color: rgba(40, 167, 69, 0.3);
        color: #e0e0e0;
    }

    input:focus, textarea:focus, select:focus {
        border-color: #28a745;
        outline-color: #28a745;
    }

    /* Tables */
    table {
        background-color: #2d2d2d;
        color: #e0e0e0;
    }

    table th {
        background-color: rgba(40, 167, 69, 0.2);
        color: #28a745;
    }

    /* Code Blocks */
    pre, code {
        background-color: #1a1a1a;
        color: #4af626;
        border: 1px solid rgba(40, 167, 69, 0.3);
        font-family: 'Quicksand', monospace;
    }

    /* Alerts */
    .alert {
        background-color: rgba(40, 167, 69, 0.1);
        border-color: rgba(40, 167, 69, 0.3);
        color: #e0e0e0;
    }

    .alert-success {
        background-color: rgba(40, 167, 69, 0.2);
        border-color: #28a745;
        color: #ffffff;
    }

    /* Progress Bar */
    .progress-bar {
        background-color: #28a745;
    }

    /* Badges */
    .badge {
        background-color: #28a745;
        color: #ffffff;
    }

    /* Pagination */
    .page-link {
        background-color: #2d2d2d;
        border-color: rgba(40, 167, 69, 0.3);
        color: #28a745;
    }

    .page-link:hover {
        background-color: rgba(40, 167, 69, 0.2);
        color: #34ce57;
    }

    .page-item.active .page-link {
        background-color: #28a745;
        border-color: #28a745;
    }
}

/* Mobile Optimizations */
@media (max-width: 768px) {
    .hero-section {
        min-height: 25vh;
    }

    .sticky-cta {
        bottom: 10px;
        right: 10px;
    }

    .card-hover:hover {
        transform: translateY(-5px);
    }
}



/* ######## Wrapper Css ######################### */
#outer-wrapper{max-width:100%;margin:0 auto;box-shadow:0 0 5px RGBA(0, 0, 0, 0.2)}
.row{width:1150px;margin:0 auto}
#content-wrapper {
margin: 0 auto;
padding: 20px 0 40px;
overflow: hidden;
}
#main-wrapper {
float: left;
width: 68%;
max-width: 800px;
}
#sidebar-wrapper {
float: right;
width: 30%;
max-width: 330px;
}
/* ######## Top Header Bar Css ######################### */
.top-bar {
   border-top:3px solid $maincolor;
background:#fff;
}
.top-bar-wrapper {
position: relative;
min-height:40px;
color: #fff;
margin:0 auto;
}
.top-bar-social, .bottom-bar-social {
float: right;
}
.bottom-bar-social {
padding:0 0;
}
.top-bar-social li, .bottom-bar-social li {
display: inline;
padding: 0;
float: left;
margin-right: 5px;
;
}
.top-bar-social .widget ul, .bottom-bar-social .widget ul {
padding: 0;
}
.top-bar-social .LinkList ul, .bottom-bar-social .LinkList ul {
text-align: center;
}
.top-bar-social #social a {
display: block;
    width: 30px;
    height: 30px;
    line-height: 30px;
    font-size: 12px;
padding-bottom:10px;
    color: #fff;
position:relative;
    background: $maincolor;
    transition: background 0.3s linear;
    -moz-transition: background 0.3s linear;
    -webkit-transition: background 0.3s linear;
    -o-transition: background 0.3s linear;
}
.top-bar-social #social a:after {
    content: "";
    position: absolute;
    bottom: 0px;
    left: 0;
    width: 1px;
    height: 1px;
    border: 15px solid transparent;
    border-bottom: 15px solid #fff;
    z-index: 0;
}
.bottom-bar-social #social a {
display: block;
width: 30px;
height: 30px;
line-height: 30px;
font-size: 15px;
color: #fff;
transition: color 0.3s linear;
-moz-transition: color 0.3s linear;
-webkit-transition: color 0.3s linear;
-o-transition: color 0.3s linear;
-webkit-border-radius: 100%;
-moz-border-radius: 100%;
border-radius: 100%;
}
