overflow: hidden;
max-width: 375px;
}
.lowerbar {margin: 0; padding: 0;}
.lowerbar .widget {margin: 0; padding: 10px 10px 0px 10px;box-sizing:border-box;}
.lowerbar h2 {
    background:$maincolor;
    color: #fff;
    font-size: 16px;
    padding: 8px 16px;
    margin: 0 0 20px;
    font-weight: 700;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    position: relative;
    text-align: center;
}
.lowerbar ul {
