/* ######## Responsive Css ######################### */
@media only screen and (max-width: 1150px) {
.row {
width: 96% !important;
margin: 0 auto;
float: none;
}
.tyard-wrapper {
    margin: 10px auto 0;
}
}
@media only screen and (max-width: 1050px) {


}
@media only screen and (max-width: 980px) {
#main-wrapper, #sidebar-wrapper {
float: none;
clear: both;
width: 100%;
max-width: 100%;
