}

.post-body {
padding:0;
}
#main-wrapper {
max-width: 100%;
}
#sidebar-wrapper {
padding-top: 20px;
}
#lowerbar-wrapper {
    width: 100%;
    max-width: 375px;
    margin: 0 auto;
